const zonas = ["zona_norte", "zona_sur", "zona_este", "zona_oeste"];

for (let i = 1; i <= 4; i++) {
    let payload = {
        device_id: `nodo_${i}`,           // ✅ antes: device_${i}
        zone: zonas[i - 1],               // ✅ antes: zona_${i}
        timestamp: Math.floor(Date.now() / 1000),
        sensors: {
            temperature_c: Number((Math.random() * 40 + 10).toFixed(2)),
            humidity_pct: Number((Math.random() * 100).toFixed(2)),
            light_raw: Number((Math.random() * 500).toFixed(0)),
            gas_detected: Math.random() > 0.7 ? 1 : 0,
            gas_mq2_raw: Number((Math.random() * 1023).toFixed(0)),
            gas_mq2_voltage: Number((Math.random() * 3.3).toFixed(2)),
            gas_mq2_percent: Number((Math.random() * 100).toFixed(2)),
            gas_mq2_ratio: Number((Math.random() * 10).toFixed(2)),
