let kpis = {};
try {
    let lines = msg.payload.split('\n')
        .filter(l => l.trim() && !l.startsWith('#'));

    // Buscar línea de cabecera para mapear columnas
    let headerLine = lines.find(l => l.includes('_value'));
    if (!headerLine) throw new Error("No se encontró cabecera");

    let headers = headerLine.split(',');
    let valueIdx = headers.indexOf('_value');
    let fieldIdx = headers.indexOf('_field');

    // Procesar cada línea de datos
    lines.forEach(line => {
        if (line.includes('_result')) {
            let cols = line.split(',');
            let field = cols[fieldIdx]?.trim();
            let value = parseFloat(cols[valueIdx]);
            if (field && !isNaN(value)) {
                // Promediar si hay varios nodos
                if (kpis[field] !== undefined) {
                    kpis[field] = (kpis[field] + value) / 2;
                } else {
                    kpis[field] = value;
                }
            }
        }
    });
} catch (e) {
    node.warn("Error parseando InfluxDB: " + e.message);
}

msg.payload = JSON.stringify({
    temperature: kpis['temperature_c'] !== undefined ? parseFloat(kpis['temperature_c'].toFixed(1)) : null,
    humidity: kpis['humidity_pct'] !== undefined ? parseFloat(kpis['humidity_pct'].toFixed(1)) : null,
    gas: kpis['gas_mq2_ppm_est'] !== undefined ? parseFloat(kpis['gas_mq2_ppm_est'].toFixed(1)) : null,
    light: kpis['light_raw'] !== undefined ? parseFloat(kpis['light_raw'].toFixed(0)) : null
});
msg.headers = {
    "Content-Type": "application/json",
